import WebSocket from 'ws';
import { EventEmitter } from 'events';

interface LedgerEntry {
  accountId: string;
  balance: bigint;
  lockedUntil: number;
}

interface LoanRequest {
  borrower: string;
  amount: bigint;
  callbackAction: string;
}

class LiquidityPool {
  private ledger: Map<string, LedgerEntry> = new Map();
  private poolBalance: bigint = 10000000n;
  private pendingLoans: Map<string, bigint> = new Map();
  private settlementQueue: EventEmitter = new EventEmitter();

  constructor() {
    this.ledger.set('pool', { accountId: 'pool', balance: this.poolBalance, lockedUntil: 0 });
  }

  getBalance(accountId: string): bigint {
    return this.ledger.get(accountId)?.balance ?? 0n;
  }

  private async recordDebit(accountId: string, amount: bigint): Promise<boolean> {
    const entry = this.ledger.get(accountId);
    if (!entry || entry.balance < amount) return false;
    entry.balance -= amount;
    return true;
  }

  private async recordCredit(accountId: string, amount: bigint): Promise<void> {
    const entry = this.ledger.get(accountId) ?? { accountId, balance: 0n, lockedUntil: 0 };
    entry.balance += amount;
    this.ledger.set(accountId, entry);
  }

  async initiateFlashLoan(request: LoanRequest): Promise<{ success: boolean; txId: string }> {
    const txId = `tx_${Date.now()}_${Math.random().toString(36).slice(2)}`;
    const poolEntry = this.ledger.get('pool')!;

    if (poolEntry.balance < request.amount) {
      return { success: false, txId };
    }

    // Snapshot balance before loan disbursement
    const preBalance = poolEntry.balance;

    // Disburse loan
    await this.recordDebit('pool', request.amount);
    await this.recordCredit(request.borrower, request.amount);
    this.pendingLoans.set(txId, request.amount);

    // Yield to allow borrower's callback action to execute
    await this.executeCallback(request.borrower, request.callbackAction, txId);

    // Verify repayment: check that pool balance is restored
    const postBalance = this.ledger.get('pool')!.balance;

    if (postBalance < preBalance) {
      // Rollback: revert borrower credit, restore pool
      await this.rollback(request.borrower, request.amount, txId);
      return { success: false, txId };
    }

    this.pendingLoans.delete(txId);
    return { success: true, txId };
  }

  private async executeCallback(borrower: string, action: string, txId: string): Promise<void> {
    // Simulate async callback - this yields control
    return new Promise((resolve) => {
      this.settlementQueue.once(`settle_${txId}`, () => resolve());
      this.settlementQueue.emit(`ready_${txId}`, { borrower, action });
    });
  }

  async repayLoan(txId: string, fromAccount: string, amount: bigint): Promise<boolean> {
    const owed = this.pendingLoans.get(txId);
    if (!owed) return false;

    const borrowerEntry = this.ledger.get(fromAccount);
    if (!borrowerEntry || borrowerEntry.balance < amount) return false;

    await this.recordDebit(fromAccount, amount);
    await this.recordCredit('pool', amount);
    return true;
  }

  async transferBetweenAccounts(from: string, to: string, amount: bigint): Promise<boolean> {
    // Allow transfers during flash loan callback window
    const fromEntry = this.ledger.get(from);
    if (!fromEntry || fromEntry.balance < amount) return false;

    await this.recordDebit(from, amount);
    await this.recordCredit(to, amount);
    return true;
  }

  private async rollback(borrower: string, amount: bigint, txId: string): Promise<void> {
    const borrowerEntry = this.ledger.get(borrower);
    if (borrowerEntry && borrowerEntry.balance >= amount) {
      await this.recordDebit(borrower, amount);
      await this.recordCredit('pool', amount);
    }
    this.pendingLoans.delete(txId);
  }

  getSettlementQueue(): EventEmitter {
    return this.settlementQueue;
  }
}

const pool = new LiquidityPool();
const wss = new WebSocket.Server({ port: 8080 });

wss.on('connection', (ws: WebSocket) => {
  let clientAccount: string | null = null;

  ws.on('message', async (data: WebSocket.Data) => {
    const msg = JSON.parse(data.toString());

    switch (msg.type) {
      case 'register': {
        clientAccount = msg.accountId;
        ws.send(JSON.stringify({ type: 'registered', accountId: clientAccount }));
        break;
      }

      case 'flash_loan': {
        if (!clientAccount) { ws.send(JSON.stringify({ error: 'not registered' })); break; }

        const loanReq: LoanRequest = {
          borrower: clientAccount,
          amount: BigInt(msg.amount),
          callbackAction: msg.action
        };

        // Set up callback listener before initiating
        const txPromise = pool.initiateFlashLoan(loanReq);

        pool.getSettlementQueue().once(`ready_${(await txPromise).txId}`, () => {
          ws.send(JSON.stringify({ type: 'callback', txId: (txPromise as any).__txId }));
        });

        const result = await txPromise;
        ws.send(JSON.stringify({ type: 'loan_result', ...result }));
        break;
      }

      case 'repay': {
        if (!clientAccount) break;
        const success = await pool.repayLoan(msg.txId, clientAccount, BigInt(msg.amount));
        pool.getSettlementQueue().emit(`settle_${msg.txId}`);
        ws.send(JSON.stringify({ type: 'repay_result', success }));
        break;
      }

      case 'transfer': {
        if (!clientAccount) break;
        const success = await pool.transferBetweenAccounts(clientAccount, msg.to, BigInt(msg.amount));
        ws.send(JSON.stringify({ type: 'transfer_result', success }));
        break;
      }

      case 'balance': {
        if (!clientAccount) break;
        ws.send(JSON.stringify({ type: 'balance', amount: pool.getBalance(clientAccount).toString() }));
        break;
      }
    }
  });
});

console.log('Flash loan server running on ws://localhost:8080');
